"""Generated FP32 FMA/add schedules for the frozen A100 NN adjoint shapes.
Indices describe arithmetic order only, independently of model parameters/data.
"""
import torch
import triton
import triton.language as tl

@triton.jit
def _add_rn(a,b):
    return tl.inline_asm_elementwise("add.rn.f32 $0, $1, $2;",constraints="=f,f,f",args=[a,b],dtype=tl.float32,is_pure=True,pack=1)

@triton.jit
def _chain(A,B,P,rows,cols,seed,M:tl.constexpr,N:tl.constexpr,K:tl.constexpr,
           SAM:tl.constexpr,SAK:tl.constexpr,SBK:tl.constexpr,SBN:tl.constexpr,
           BASE:tl.constexpr,LENGTH:tl.constexpr):
    acc=seed
    for chunk in range(tl.cdiv(LENGTH,16)):
        q=chunk*16+tl.arange(0,16)
        k=tl.load(P+BASE+q,q<LENGTH,0).to(tl.int64)
        a=tl.load(A+rows[:,None]*SAM+k[None,:]*SAK,(rows[:,None]<M)&(q[None,:]<LENGTH)&(k[None,:]<K),0)
        b=tl.load(B+k[:,None]*SBK+cols[None,:]*SBN,(q[:,None]<LENGTH)&(k[:,None]<K)&(cols[None,:]<N),0)
        acc=tl.dot(a,b,acc,input_precision="ieee")
    return acc

@triton.jit
def _nn_k512_n128(A,B,P,C,M:tl.constexpr,N:tl.constexpr,K:tl.constexpr,SAM:tl.constexpr,SAK:tl.constexpr,SBK:tl.constexpr,SBN:tl.constexpr):
    rows=tl.program_id(0).to(tl.int64)*32+tl.arange(0,32).to(tl.int64)
    cols=tl.program_id(1).to(tl.int64)*32+tl.arange(0,32).to(tl.int64)
    zero=tl.full((32,32),0,tl.float32)
    v0=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,0,86)
    v1=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,96,86)
    v2=_add_rn(v0,v1)
    v3=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,192,86)
    v4=_add_rn(v2,v3)
    v5=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,288,86)
    v6=_add_rn(v4,v5)
    v7=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,384,86)
    v8=_add_rn(v6,v7)
    v9=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,480,82)
    v10=_add_rn(v8,v9)
    tl.store(C+rows[:,None]*N+cols[None,:],v10,(rows[:,None]<M)&(cols[None,:]<N))

@triton.jit
def _nn_k384_n96(A,B,P,C,M:tl.constexpr,N:tl.constexpr,K:tl.constexpr,SAM:tl.constexpr,SAK:tl.constexpr,SBK:tl.constexpr,SBN:tl.constexpr):
    rows=tl.program_id(0).to(tl.int64)*32+tl.arange(0,32).to(tl.int64)
    cols=tl.program_id(1).to(tl.int64)*32+tl.arange(0,32).to(tl.int64)
    zero=tl.full((32,32),0,tl.float32)
    v0=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,0,128)
    v1=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,128,128)
    v2=_add_rn(v0,v1)
    v3=_chain(A,B,P,rows,cols,zero,M,N,K,SAM,SAK,SBK,SBN,256,128)
    v4=_add_rn(v2,v3)
    tl.store(C+rows[:,None]*N+cols[None,:],v4,(rows[:,None]<M)&(cols[None,:]<N))

